    def decode_wrong_operator_error(self, data: str) -> tuple[Any, ...]:
        """Decodes WrongOperator() custom error arguments."""
        raw = bytes.fromhex(data.removeprefix("0x"))
        if raw[:4] != bytes.fromhex("2b3b1add"):
            raise ValueError("Custom error selector mismatch")
        return _strict_abi_decode([], raw[4:])
